package com.vidadomu.corte.model

import kotlinx.serialization.Serializable

@Serializable
enum class ClipKind {
    VIDEO, AUDIO, IMAGE,

    /** A title generated by the app; [Clip.mediaId] is empty and [Clip.text] holds the content. */
    TEXT;

    val trackKind: TrackKind get() = if (this == AUDIO) TrackKind.AUDIO else TrackKind.VIDEO

    /** Images and titles have no source length: they can be trimmed to any duration. */
    val unboundedSource: Boolean get() = this == IMAGE || this == TEXT
}

@Serializable
enum class TextAlign { LEFT, CENTER, RIGHT }

/**
 * Content and look of a title. Placement, scale, rotation, opacity, fades and keyframes come from
 * the clip's [VideoProps] like any other layer.
 */
@Serializable
data class TextProps(
    val text: String = "Texto",
    /** Font size as a fraction of the frame height. */
    val size: Double = 0.08,
    val colorArgb: Int = 0xFFFFFFFF.toInt(),
    val bold: Boolean = true,
    val align: TextAlign = TextAlign.CENTER,
    val shadow: Boolean = true,
    /** Box behind the text; 0 = no box. */
    val boxOpacity: Double = 0.0,
    val boxColorArgb: Int = 0xFF000000.toInt(),
)

@Serializable
enum class FitMode { FIT, FILL, STRETCH }

@Serializable
data class Crop(val left: Float = 0f, val top: Float = 0f, val right: Float = 0f, val bottom: Float = 0f) {
    val isIdentity: Boolean get() = left == 0f && top == 0f && right == 0f && bottom == 0f
}

/**
 * Primary colour correction. 0 = neutral for every field. Rendered: exposure (stops), contrast,
 * saturation, temperature, tint, fade and the LUT. highlights/shadows/sharpen are stored but not
 * rendered yet (they are not offered in the UI).
 */
@Serializable
data class ColorProps(
    val exposure: Float = 0f,
    val contrast: Float = 0f,
    val saturation: Float = 0f,
    val highlights: Float = 0f,
    val shadows: Float = 0f,
    val temperature: Float = 0f,
    val tint: Float = 0f,
    val fade: Float = 0f,
    val sharpen: Float = 0f,
    val lutUri: String? = null,
) {
    val isNeutral: Boolean get() = this == ColorProps()
}

/**
 * Static (non-animated) visual properties. Animated values come from [Clip.keyframes] and override
 * the static value when a keyframe track exists for that parameter.
 * Position is in frame units: (1, 0) moves the layer by one full frame width to the right.
 */
@Serializable
data class VideoProps(
    val opacity: Double = 1.0,
    val positionX: Double = 0.0,
    val positionY: Double = 0.0,
    val scale: Double = 1.0,
    val rotationDeg: Double = 0.0,
    val flipH: Boolean = false,
    val flipV: Boolean = false,
    val crop: Crop = Crop(),
    val fit: FitMode = FitMode.FIT,
    /** Fade from black at the head / to black at the tail. */
    val fadeInUs: Long = 0,
    val fadeOutUs: Long = 0,
    val color: ColorProps = ColorProps(),
)

@Serializable
data class AudioProps(
    val gainDb: Double = 0.0,
    /** -1 = hard left, 0 = centre, +1 = hard right. */
    val pan: Double = 0.0,
    val muted: Boolean = false,
    val fadeInUs: Long = 0,
    val fadeOutUs: Long = 0,
)

/**
 * A clip places a span of a media file on a track.
 *
 * Source of truth: [timelineStartUs], [durationUs] (timeline time), [sourceInUs] and [speed].
 * The consumed source span is derived: sourceOut = sourceIn + speed * duration. Keeping the timeline
 * duration as the integer truth makes ripple arithmetic exact: splitting never loses or gains time.
 */
@Serializable
data class Clip(
    val id: String,
    val kind: ClipKind,
    val mediaId: String,
    val timelineStartUs: Long,
    val durationUs: Long,
    val sourceInUs: Long = 0,
    val speed: Rational = Rational.ONE,
    /** Clips sharing a linkId (typically the video and audio of one file) edit together. */
    val linkId: String? = null,
    /** Clips sharing a syncGroupId move together, keeping their relative offsets. */
    val syncGroupId: String? = null,
    val name: String = "",
    val video: VideoProps = VideoProps(),
    val audio: AudioProps = AudioProps(),
    val keyframes: Map<AnimParam, KeyframeTrack> = emptyMap(),
    /** Only for [ClipKind.TEXT]. */
    val text: TextProps? = null,
) {
    init {
        require(durationUs > 0) { "clip $id must have positive duration ($durationUs)" }
        require(sourceInUs >= 0) { "clip $id sourceIn must be >= 0 ($sourceInUs)" }
        require(speed.num > 0) { "clip $id speed must be positive" }
    }

    val endUs: Long get() = timelineStartUs + durationUs
    val range: TimeRange get() = TimeRange(timelineStartUs, endUs)
    val sourceOutUs: Long get() = sourceInUs + speed.scale(durationUs)

    /** Source time displayed at timeline time [t] (must be inside the clip). */
    fun sourceTimeAt(t: Long): Long = sourceInUs + speed.scale(t - timelineStartUs)

    fun contains(t: Long): Boolean = t >= timelineStartUs && t < endUs

    fun keyframeValue(param: AnimParam, timelineTimeUs: Long): Double? =
        keyframes[param]?.valueAt(timelineTimeUs - timelineStartUs)

    fun withKeyframesShifted(deltaUs: Long): Clip =
        if (deltaUs == 0L || keyframes.isEmpty()) this
        else copy(keyframes = keyframes.mapValues { it.value.shifted(deltaUs) })
}
